def band_minutes(start: int, end: int) -> dict:
    if start > end:
        raise ValueError("start must be <= end")

    length = end - start
    if length < 5:
        return {"day": 0, "night": 0, "weekend": 0}

    WEEK = 10080
    PER_WEEK = {"day": 4800, "night": 2400, "weekend": 2880}

    def count_band(a, b, band):
        """Count minutes in [a, b) (0 <= a < b <= 10080) in the given band."""
        cnt = 0
        for day in range(7):
            ds = day * 1440
            de = (day + 1) * 1440
            lo = max(a, ds)
            hi = min(b, de)
            if lo >= hi:
                continue
            if day >= 5:
                if band == "weekend":
                    cnt += hi - lo
            else:
                if band == "day":
                    lb = max(lo, ds + 360)
                    hb = min(hi, ds + 1320)
                    cnt += max(0, hb - lb)
                elif band == "night":
                    lb = max(lo, ds)
                    hb = min(hi, ds + 360)
                    cnt += max(0, hb - lb)
                    lb = max(lo, ds + 1320)
                    hb = min(hi, de)
                    cnt += max(0, hb - lb)
        return cnt

    full_cycles = length // WEEK
    remainder = length % WEEK

    start_mod = start % WEEK
    end_mod = end % WEEK

    if remainder == 0:
        pd = pn = pw = 0
    elif end_mod > start_mod:
        pd = count_band(start_mod, end_mod, "day")
        pn = count_band(start_mod, end_mod, "night")
        pw = count_band(start_mod, end_mod, "weekend")
    else:  # wraps past the week boundary
        pd = count_band(start_mod, WEEK, "day") + count_band(0, end_mod, "day")
        pn = count_band(start_mod, WEEK, "night") + count_band(0, end_mod, "night")
        pw = count_band(start_mod, WEEK, "weekend") + count_band(0, end_mod, "weekend")

    raw_day = full_cycles * PER_WEEK["day"] + pd
    raw_night = full_cycles * PER_WEEK["night"] + pn
    raw_weekend = full_cycles * PER_WEEK["weekend"] + pw

    def round_up(n):
        return 0 if n == 0 else (n + 14) // 15 * 15

    return {
        "day": round_up(raw_day),
        "night": round_up(raw_night),
        "weekend": round_up(raw_weekend),
    }
