import re


def expand_slots(spec: str) -> list[str]:
    if not spec.strip():
        return []

    tokens = [t.strip() for t in spec.split(",")]

    for t in tokens:
        if not t:
            raise ValueError("empty token in slot spec")

    slot_re = re.compile(r"^([A-Z])([1-9][0-9]?)$")
    result: list[str] = []

    for token in tokens:
        is_remove = token.startswith("!")
        if is_remove:
            token = token[1:]
            if not token:
                raise ValueError("invalid removal token")

        if "-" in token:
            parts = token.split("-")
            if len(parts) != 2:
                raise ValueError(f"invalid range token: {token}")
            m1 = slot_re.match(parts[0])
            m2 = slot_re.match(parts[1])
            if not m1 or not m2:
                raise ValueError(f"invalid slot in range: {token}")
            if m1.group(1) != m2.group(1):
                raise ValueError(f"mismatched letters in range: {token}")
            start = int(m1.group(2))
            end = int(m2.group(2))
            letter = m1.group(1)
            step = 1 if start <= end else -1
            slots = [f"{letter}{n}" for n in range(start, end + step, step)]
        else:
            m = slot_re.match(token)
            if not m:
                raise ValueError(f"invalid slot token: {token}")
            slots = [token]

        if is_remove:
            for slot in slots:
                if slot in result:
                    result.remove(slot)
        else:
            for slot in slots:
                if slot not in result:
                    result.append(slot)

    return result
