def top_spenders(events: list[dict], k: int) -> list[tuple[str, int]]:
    # Stable sort by timestamp preserves original relative order for equal ts
    sorted_events = sorted(events, key=lambda e: e["ts"])

    orders: dict[str, dict] = {}  # order_id -> {amount, customer, cancelled}
    customer_earliest_buy: dict[str, int] = {}

    for event in sorted_events:
        order_id = event["order"]
        etype = event["type"]

        if etype == "buy":
            if order_id not in orders:
                customer = event["customer"]
                cents = event["cents"]
                orders[order_id] = {"amount": cents, "customer": customer, "cancelled": False}
                if customer not in customer_earliest_buy:
                    customer_earliest_buy[customer] = event["ts"]

        elif etype == "refund":
            if order_id in orders and not orders[order_id]["cancelled"]:
                cents = event["cents"]
                orders[order_id]["amount"] = max(orders[order_id]["amount"] - cents, 0)

        elif etype == "cancel":
            if order_id in orders:
                orders[order_id]["amount"] = 0
                orders[order_id]["cancelled"] = True

    # Sum current order amounts per customer
    customer_totals: dict[str, int] = {}
    for info in orders.values():
        cust = info["customer"]
        customer_totals[cust] = customer_totals.get(cust, 0) + info["amount"]

    # Filter to positive totals only
    ranked = [(name, total) for name, total in customer_totals.items() if total > 0]

    # Rank: total desc, earliest-accepted-buy ts asc, name asc
    ranked.sort(key=lambda x: (-x[1], customer_earliest_buy[x[0]], x[0]))

    return ranked[:k]
