def parse_stanza(text: str) -> dict:
    def strip_comment(line: str) -> str:
        in_quoted = False
        for i, ch in enumerate(line):
            if ch == '"':
                in_quoted = not in_quoted
            elif ch == '#' and not in_quoted:
                return line[:i]
        return line

    def convert_scalar(raw: str):
        if raw.isdigit():
            return int(raw)
        if raw.startswith('-') and raw[1:].isdigit():
            return int(raw)
        if raw == 'yes':
            return True
        if raw == 'no':
            return False
        return raw

    def parse_value(raw: str):
        raw = raw.strip()
        if len(raw) >= 2 and raw[0] == '"' and raw[-1] == '"':
            return raw[1:-1]
        if '|' in raw:
            return [convert_scalar(p.strip()) for p in raw.split('|')]
        return convert_scalar(raw)

    result = {}
    current_section = None

    for line in text.split('\n'):
        line = strip_comment(line).strip()
        if not line:
            continue

        if line.startswith('[') and line.endswith(']'):
            name = line[1:-1].strip()
            if not name:
                raise ValueError("Empty section name")
            if name not in result:
                result[name] = {}
            current_section = name
        else:
            if '=' not in line:
                raise ValueError(f"Line without '=': {line}")
            idx = line.index('=')
            key = line[:idx].strip()
            if not key:
                raise ValueError(f"Empty key in line: {line}")
            raw_value = line[idx + 1:].strip()
            value = parse_value(raw_value)

            if current_section is None:
                if "" not in result:
                    result[""] = {}
                result[""][key] = value
            else:
                result[current_section][key] = value

    return result
