def run_tally(program: str, max_steps: int) -> tuple[str, list[int]]:
    tokens = program.split()
    n = len(tokens)

    stack: list[int] = []
    output: list[int] = []
    pc = 0
    steps = 0

    def is_int(s: str) -> bool:
        if s == "":
            return False
        if s[0] == "-":
            if len(s) == 1:
                return False
            return s[1:].isdigit()
        return s.isdigit()

    while True:
        if pc == n:
            return ("done", output)
        if steps == max_steps:
            return ("limit", output)

        token = tokens[pc]
        steps += 1

        if token.startswith("jmp:"):
            rest = token[4:]
            if not is_int(rest):
                return ("fault", output)
            k = int(rest)
            target = pc + k
            if target < 0 or target > n:
                return ("fault", output)
            pc = target
            continue

        if token.startswith("jz:"):
            rest = token[3:]
            if not is_int(rest):
                return ("fault", output)
            k = int(rest)
            if len(stack) < 1:
                return ("fault", output)
            val = stack.pop()
            if val == 0:
                target = pc + k
                if target < 0 or target > n:
                    return ("fault", output)
                pc = target
            else:
                pc += 1
            continue

        if token == "dup":
            if len(stack) < 1:
                return ("fault", output)
            stack.append(stack[-1])
            pc += 1
            continue

        if token == "drop":
            if len(stack) < 1:
                return ("fault", output)
            stack.pop()
            pc += 1
            continue

        if token == "swap":
            if len(stack) < 2:
                return ("fault", output)
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
            continue

        if token in ("add", "sub", "mul"):
            if len(stack) < 2:
                return ("fault", output)
            b = stack.pop()
            a = stack.pop()
            if token == "add":
                stack.append(a + b)
            elif token == "sub":
                stack.append(a - b)
            else:
                stack.append(a * b)
            pc += 1
            continue

        if token == "out":
            if len(stack) < 1:
                return ("fault", output)
            output.append(stack.pop())
            pc += 1
            continue

        if is_int(token):
            stack.append(int(token))
            pc += 1
            continue

        return ("fault", output)
