def plan_rounds(deps: dict, capacity: int) -> list[list[str]]:
    if capacity < 1:
        raise ValueError("capacity must be at least 1")

    for task, prerequisites in deps.items():
        for prereq in prerequisites:
            if prereq not in deps:
                raise ValueError(f"Prerequisite {prereq!r} not in deps")

    if not deps:
        return []

    # Compute fixed number of direct dependents for each task
    dependents = {task: 0 for task in deps}
    for task, prereqs in deps.items():
        for prereq in prereqs:
            dependents[prereq] += 1

    done = set()
    rounds: list[list[str]] = []

    while len(done) < len(deps):
        # Find ready tasks: not done, and all prerequisites done in earlier rounds
        ready = [
            task
            for task, prereqs in deps.items()
            if task not in done and all(p in done for p in prereqs)
        ]

        if not ready:
            raise ValueError("Dependency cycle detected")

        # Sort by direct dependents (desc), then name (asc)
        ready.sort(key=lambda t: (-dependents[t], t))

        # The first `capacity` tasks run in this round
        current_round = ready[:capacity]
        rounds.append(current_round)
        done.update(current_round)

    return rounds
