def number_outline(entries: list[tuple[int, str]]) -> list[str]:
    """Number the entries of an outline."""

    def _spreadsheet(n: int) -> str:
        """Convert an integer >= 1 to lowercase spreadsheet column style."""
        out = []
        while n > 0:
            n -= 1
            out.append(chr(ord('a') + n % 26))
            n //= 26
        return ''.join(reversed(out))

    def _roman(n: int) -> str:
        """Convert an integer (1..3999) to lowercase subtractive Roman numerals."""
        table = (
            (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
            (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
            (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'), (1, 'i'),
        )
        out = []
        for value, sym in table:
            while n >= value:
                out.append(sym)
                n -= value
        return ''.join(out)

    if not entries:
        return []

    counters: dict[int, int] = {}
    prev_eff: int = 0
    lines: list[str] = []

    for i, (req_depth, title) in enumerate(entries):
        if req_depth < 1:
            raise ValueError(f"Requested depth {req_depth} is below 1")

        if i == 0:
            eff = 1
        else:
            eff = min(req_depth, prev_eff + 1)

        counters[eff] = counters.get(eff, 0) + 1
        for lvl in sorted(counters, reverse=True):
            if lvl > eff:
                del counters[lvl]

        prev_eff = eff

        parts = []
        for lvl in range(1, eff + 1):
            val = counters.get(lvl, 0)
            mod = lvl % 3
            if mod == 1:
                parts.append(str(val))
            elif mod == 2:
                parts.append(_spreadsheet(val))
            else:
                parts.append(_roman(val))

        label = ".".join(parts)
        indent = " " * (2 * (eff - 1))
        lines.append(f"{indent}{label}) {title}")

    return lines
